extra_css:
/* theme: citypop-dusk (2026-10-27) */
:root,:root:not(x){--bg:#17143a;--fg:#f4efff;--muted:#b7b3d9;--line:#353070;--card:#211d4d;--soft:#2a2560;--accent:#ff7eb6;--accent2:#ffb15c}
@media (prefers-color-scheme:dark){:root{--bg:#17143a;--fg:#f4efff;--muted:#b7b3d9;--line:#353070;--card:#211d4d;--soft:#2a2560;--accent:#ff7eb6;--accent2:#ffb15c}}
body{background:linear-gradient(180deg,#2b1f5c 0,#17143a 420px) no-repeat,var(--bg)}
header{background:linear-gradient(90deg,#ff8a5c22,#ff7eb622,#5cc8d622),#17143a;border-bottom:0;box-shadow:0 3px 0 #ffb15c,0 6px 0 #ff7eb6,0 9px 0 #8e6bff}
.wrap>.layout{padding-top:34px}
.logo,.hero h1,article h1,.sec-h,article h2,.picks-h,.next-h,aside .box-h{font-family:"RocknRoll One","Hiragino Sans",sans-serif;font-weight:400}
.logo{color:#fff}.logo span{background:linear-gradient(90deg,#ffb15c,#ff7eb6);-webkit-background-clip:text;background-clip:text;color:transparent}
.gnav a{background:#2a2560;color:#f4efff;border-radius:6px}
.gnav a:hover,.gnav a.on{background:linear-gradient(90deg,#ffb15c,#ff7eb6);color:#17143a}
.hero-img{border-radius:6px;box-shadow:0 10px 30px #ff7eb633}
.sec-h{border-bottom:0;background:linear-gradient(90deg,#ffb15c,#ff7eb6,#8e6bff) bottom/100% 4px no-repeat}
.card{border:0;border-radius:4px;background:#211d4d;box-shadow:0 0 0 1px #353070}
.thumb{border-radius:4px 4px 0 0}
.card:hover{box-shadow:0 0 0 2px #ff7eb6,8px 8px 0 #ffb15c55}
.tag{background:#5cc8d6;color:#17143a;font-weight:700;border-radius:4px}
article h2{background:#211d4d;border-left:0;border-radius:4px;padding:10px 14px 10px 30px;position:relative}
article h2::before{content:"";position:absolute;left:10px;top:10px;bottom:10px;width:10px;background:linear-gradient(180deg,#ffb15c 0 33%,#ff7eb6 33% 66%,#8e6bff 66%)}
article h3{border-bottom:2px solid #5cc8d6}
.toc{border-top:4px solid #ffb15c}
.note{border-left-color:#5cc8d6}
.picks{border:2px solid #ff7eb6;border-radius:6px}
.picks-h::before{content:"♪ ";color:#ffb15c}
.next{border-color:#ffb15c;background:#211d4d;border-radius:6px}
.avatar{background:radial-gradient(circle,#17143a 0 18%,#ff7eb6 19% 100%)}
aside .box-h{border-bottom:3px solid #ff7eb6}
.mini b{background:#ffb15c;color:#17143a}
th{background:#2a2560}
footer{background:#100d2c;border-top:0;box-shadow:0 -3px 0 #8e6bff,0 -6px 0 #ff7eb6,0 -9px 0 #ffb15c}

/* hero-base: 2026-10-27 トップの見せ場の共通部分 */
.hx{padding:24px 0 6px}.hx-eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:var(--accent);margin:0 0 8px}
.hx-h1{font-size:clamp(28px,5vw,46px);line-height:1.3;margin:0 0 14px}.hx-h1 em{font-style:normal;color:var(--accent)}
.hx-lead{color:var(--muted);font-size:15px;margin:0 0 22px;max-width:680px}
.hx-chips{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 26px}.hx-chips a{text-decoration:none;font-size:13px;padding:5px 12px}
.hx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin:0 0 22px}.hx-vs p{margin:0;font-size:13px;color:var(--muted)}
.hx-k{font-size:12px;color:var(--muted)}.hx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;line-height:1.35;margin:4px 0}
.hx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}.hx-stats b{display:block;line-height:1.1;font-variant-numeric:tabular-nums}.hx-stats span{font-size:12px;color:var(--muted)}
.hx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.hx-steps strong{display:block;font-size:15px}.hx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.hx-vs,.hx-steps{grid-template-columns:1fr}.hx-stats{gap:6px}.hx-mid{justify-self:center}.hx-vs{text-align:center}}
[data-seq]>*{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s}[data-seq]>.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-seq]>*{opacity:1;transform:none;transition:none}}

/* hero: record-deck (2026-10-27) */
.hx-city .hx-h1{font-family:"RocknRoll One",sans-serif;font-weight:400}.hx-city .hx-h1 em{background:linear-gradient(90deg,#ffb15c,#ff7eb6);-webkit-background-clip:text;background-clip:text;color:transparent}
.hx-deck{display:flex;gap:22px;align-items:center;background:linear-gradient(135deg,#2a2560,#211d4d);border-radius:8px;padding:20px;box-shadow:0 0 0 1px #353070,10px 10px 0 #ff7eb633}
.hx-vinyl{flex:0 0 150px;height:150px;border-radius:50%;background:repeating-radial-gradient(circle,#111 0 2px,#1c1c1c 2px 4px);display:flex;align-items:center;justify-content:center;animation:hxspin 4s linear infinite;box-shadow:0 0 0 4px #0c0a20}
.hx-label{width:66px;height:66px;border-radius:50%;background:linear-gradient(135deg,#ffb15c,#ff7eb6);display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#17143a;text-align:center;line-height:1.2;padding:4px}
.hx-label span.in{animation:hxfade .5s}@keyframes hxfade{from{opacity:0}to{opacity:1}}@keyframes hxspin{to{transform:rotate(360deg)}}
.hx-deck-r{flex:1}.hx-np{font-family:"RocknRoll One",sans-serif;font-size:12px;letter-spacing:.2em;color:#5cc8d6}.hx-q{min-height:58px;font-size:16px;margin:6px 0 10px}
.hx-go{display:inline-block;background:linear-gradient(90deg,#ffb15c,#ff7eb6);color:#17143a;text-decoration:none;font-weight:700;font-size:13px;padding:7px 16px;border-radius:4px}
.hx-artists{align-items:center}.hx-artists span{font-size:13px;color:#b7b3d9}.hx-artists a{background:#211d4d;color:#f4efff;border-radius:4px;box-shadow:0 0 0 1px #353070}.hx-artists a:hover{box-shadow:0 0 0 2px #ff7eb6}
.hx-city .hx-vs{background:#211d4d;border-radius:6px;padding:20px 14px;position:relative;overflow:hidden}
.hx-city .hx-vs::after{content:"";position:absolute;left:0;right:0;bottom:0;height:6px;background:linear-gradient(90deg,#ffb15c 0 33%,#ff7eb6 33% 66%,#8e6bff 66%)}
.hx-city .hx-v{font-family:"RocknRoll One",sans-serif;font-weight:400}.hx-city .hx-side.on .hx-v{color:#ff7eb6}.hx-city .hx-mid{color:#5cc8d6;font-family:"RocknRoll One",sans-serif}
.hx-city .hx-stats div{background:#0c0a20;border-radius:4px;padding:12px;text-align:center;box-shadow:inset 0 0 0 1px #353070}
.hx-city .hx-stats b{font-family:"RocknRoll One",sans-serif;font-size:clamp(30px,5vw,44px);color:#5cc8d6;text-shadow:0 0 12px #5cc8d6aa}
.hx-city .hx-steps li{background:#211d4d;border-radius:4px;padding:12px 14px;border-top:4px solid #ffb15c}.hx-city .hx-steps li:nth-child(2){border-top-color:#ff7eb6}.hx-city .hx-steps li:nth-child(3){border-top-color:#8e6bff}
.hx-city .hx-steps b{font-family:"RocknRoll One",sans-serif;font-size:12px;color:#ffb15c}
@media (max-width:560px){.hx-deck{flex-direction:column;text-align:center}}
@media (prefers-reduced-motion:reduce){.hx-vinyl{animation:none}}

/* article-base: 2026-10-27 記事ページの共通部分 */
.ax-time{display:inline-block;font-size:12px;margin-left:8px}
.ax-prog{position:fixed;left:0;right:0;top:0;height:4px;z-index:50;pointer-events:none}.ax-prog i{display:block;height:100%;width:0}
.toc li.now>a{font-weight:700}
.ax-tick{cursor:pointer}li.ax-tick{position:relative;padding-left:30px}ul>li.ax-tick{list-style:none}ul>li.ax-tick::marker{content:""!important}
li.ax-tick::before,tr.ax-tick td:first-child::before{content:"";position:absolute;left:4px;top:.45em;width:16px;height:16px;border:2px solid currentColor;border-radius:4px;opacity:.55}
.ax-tick.done{opacity:.55;text-decoration:line-through}li.ax-tick.done::after,tr.ax-tick.done td:first-child::after{content:"✓";position:absolute;left:7px;top:.05em;font-weight:800}
tr.ax-tick td:first-child{position:relative;padding-left:32px}tr.ax-tick td:first-child::before{left:8px;top:.6em}tr.ax-tick.done td:first-child::after{left:11px;top:.2em}
.ax-copy{display:block;margin:10px 0 0 auto;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
@media print{.ax-prog,.ax-size,.ax-copy{display:none}}

/* article: liner-notes (2026-10-27) */
.ax-prog{background:#100d2c}.ax-prog i{background:linear-gradient(90deg,#ffb15c,#ff7eb6,#8e6bff)}
.ax-time{font-family:"RocknRoll One",sans-serif;color:#5cc8d6;border:1px solid #5cc8d6;border-radius:4px;padding:0 8px}
article h1{font-family:"RocknRoll One",sans-serif;font-weight:400}
.lead{background:#211d4d;border:0;border-left:6px solid #5cc8d6;border-radius:4px}.lead strong{font-size:0}.lead strong::before{content:"LINER NOTES";font-size:12px;letter-spacing:.25em;color:#5cc8d6;font-family:"RocknRoll One",sans-serif}
.toc{counter-reset:tr;background:#0c0a20;border:0;box-shadow:inset 0 0 0 1px #353070;border-radius:6px}.toc strong{font-size:0}.toc strong::before{content:"TRACK LIST";font-size:13px;letter-spacing:.25em;font-family:"RocknRoll One",sans-serif;color:#ffb15c}
.toc ol{list-style:none;padding-left:0}.toc li{counter-increment:tr;display:flex;gap:10px;padding:4px 0;border-bottom:1px solid #1e1a48}.toc li::before{content:counter(tr,decimal-leading-zero);font-family:"RocknRoll One",sans-serif;color:#8e6bff;flex:0 0 26px}
.toc li.now::before{content:"▶";color:#ff7eb6}
article{counter-reset:th}article h2{counter-increment:th}article h2::after{content:"TRACK " counter(th,decimal-leading-zero);display:block;font-size:11px;letter-spacing:.25em;color:#5cc8d6;margin-top:2px}
article h2.ax-sum::after{content:"OUTRO"}
article ul li::marker{content:"♪ ";color:#ffb15c}
article blockquote,article .note{border-left-color:#ff7eb6}

/* category-base: 2026-10-27 カテゴリページの共通部分 */
.cx-page .cards{counter-reset:none}
.cx-page .card{position:relative;animation:cxin .5s both;animation-delay:calc(var(--i,0)*60ms)}
@keyframes cxin{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.cx-page .card{animation:none}}
.cx-head{position:relative;margin:4px 0 6px}.cx-head h1{margin:0}
.cx-intro{margin:8px 0 0}
.cx-meter{display:flex;align-items:center;gap:10px;margin:12px 0 0;font-size:13px}.cx-meter span{white-space:nowrap}.cx-meter b{font-size:1.25em}
.cx-meter i{position:relative;flex:1;height:8px;border-radius:99px;overflow:hidden;max-width:240px}
.cx-meter i::after{content:"";position:absolute;left:0;top:0;bottom:0;background:var(--cxm,#888);width:var(--w,0);transition:width .9s ease}
.cx-sort{display:inline-flex;gap:4px;margin:12px 0 0}.cx-sort button{font:inherit;font-size:13px;padding:4px 12px;cursor:pointer}
.cx-badge{position:absolute;top:10px;right:10px;font-size:12px;font-weight:700;padding:2px 10px;z-index:2}
.cx-others{margin:18px 0 8px}.cx-others strong{display:block;font-size:13px;margin-bottom:8px}.cx-others div{display:flex;flex-wrap:wrap;gap:8px}
.cx-others a{text-decoration:none;font-size:14px;padding:5px 12px}.cx-others small{margin-left:6px;opacity:.7}

/* category: record-sleeve (2026-10-27) */
.cx-sleeve{display:flex;align-items:center;gap:22px;padding:20px;border-radius:10px;background:linear-gradient(135deg,#ff7eb6 0,#ffb15c 35%,#2b1f5c 35.2%,#17143a);overflow:hidden}
.cx-disc{flex:0 0 150px;height:150px;border-radius:50%;background:repeating-radial-gradient(circle,#111 0 2px,#1e1e1e 2px 4px);box-shadow:0 6px 20px #0008;display:flex;align-items:center;justify-content:center;animation:cxspin 9s linear infinite}
.cx-disc i{width:52px;height:52px;border-radius:50%;background:radial-gradient(circle,#17143a 0 5px,#ff7eb6 5px 100%);box-shadow:inset 0 0 0 6px #ffb15c}
@keyframes cxspin{to{transform:rotate(360deg)}}@media (prefers-reduced-motion:reduce){.cx-disc{animation:none}}
.cx-main{flex:1;min-width:0;background:#17143acc;border-radius:8px;padding:12px 16px}
.cx-eye{font-family:"RocknRoll One",sans-serif;font-size:12px;letter-spacing:.2em;color:#5cc8d6}
.cx-sleeve h1{font-family:"RocknRoll One",sans-serif;font-weight:400;font-size:clamp(26px,4vw,34px);color:#fff;text-shadow:3px 3px 0 #8e6bff}.cx-sleeve h1 small{font-size:.5em;color:#ffb15c;text-shadow:none}
.cx-page{--cxm:#ff7eb6}.cx-meter i{background:#100d2c}.cx-meter b{color:#ffb15c}
.cx-sort button{background:#100d2c;color:#e6e0ff;border:1px solid #5cc8d6;border-radius:4px;font-family:"RocknRoll One",sans-serif}.cx-sort button.on{background:#5cc8d6;color:#100d2c}
.cx-page .card::before{content:attr(data-no);position:absolute;top:10px;left:10px;z-index:2;font-family:"RocknRoll One",sans-serif;font-size:11px;letter-spacing:.2em;color:#100d2c;background:#5cc8d6;border-radius:4px;padding:1px 8px}
.cx-badge{background:#ff7eb6;color:#100d2c;border-radius:4px;font-family:"RocknRoll One",sans-serif}
.cx-others a{background:#211d4d;border:1px solid #8e6bff;border-radius:99px;color:#fff}.cx-others a::before{content:"♪ ";color:#ffb15c}.cx-others strong{font-family:"RocknRoll One",sans-serif;color:#ffb15c}
@media (max-width:560px){.cx-sleeve{flex-direction:column;align-items:stretch}.cx-disc{flex-basis:auto;width:110px;height:110px;align-self:center}}

/* shop-btn-dusk: 2026-10-30 本人指示「バックに合った背景色に」。どの生成スクリプトより後ろに置く */
.btn{background:#2a2560;color:color-mix(in srgb,var(--bc) 55%,#fff);font-weight:800}.btn:hover{background:#353070}.btn.amz{--bc:#ffad33;color:#ffc266;border-color:#ffad33;box-shadow:0 0 10px #ffad3333}.btn.rkt{--bc:#ff5c7a;color:#ff9ab8;border-color:#ff5c7a;box-shadow:0 0 10px #ff5c7a33}.btn.vc{--bc:#5cc8d6;color:#8fdde6;border-color:#5cc8d6}
